package com.hexxon.api.notification;
import com.hexxon.api.lead.ContactLead;
import java.util.Map; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient;
/** Webhook-based commercial notification; URL is configured only in backend environment. */
@Service public class CommercialLeadNotificationService { private static final Logger log = LoggerFactory.getLogger(CommercialLeadNotificationService.class); private final String webhookUrl; private final RestClient client = RestClient.create(); public CommercialLeadNotificationService(@Value("${hexxon.marketing.commercial-notification-webhook-url}") String webhookUrl) { this.webhookUrl = webhookUrl; } public void notifyNewLead(ContactLead lead) { if (webhookUrl == null || webhookUrl.isBlank()) { log.info("Commercial notification provider not configured; leadId={}", lead.getId()); return; } try { client.post().uri(webhookUrl).body(Map.of("event", "marketing_lead_created", "leadId", lead.getId().toString(), "laboratoryName", lead.getLaboratoryName(), "interest", lead.getInterest().name())).retrieve().toBodilessEntity(); } catch (Exception exception) { log.warn("Commercial notification delivery failed; leadId={}", lead.getId()); } } }
